  "industry": {
    "industry": "Residential Plumbing Contractor (Home Services)",
    "activities": [
      "24/7 emergency plumbing repairs",
      "Water heater repair, installation, flush, and tankless systems",
      "Drain cleaning, sewer camera inspections, and main water/sewer line repair and replacement",
      "Water softeners, water filtration, and water treatment systems",
      "New construction and remodel plumbing",
      "Gas line installation and repairs, bury hydrants, garbage disposals, and radiant heating",
      "Annual plumbing maintenance plans (Buffalo Bucks)"
    ],
    "claims": [
      {
        "statement": "Running Water Plumbing provides water heater, drain, sewer, water line, water treatment, and 24/7 emergency repair services at flat-rate pricing.",
        "label": "fact",
        "sourceUrl": "https://runningwaterplumbingidaho.com/",
        "quote": "We handle water heaters , drains, sewer and water lines , water treatment and everyday repairs, with 24/7 emergency service , flat-rate pricing"
      },
      {
        "statement": "The company also performs residential new construction and remodel plumbing.",
        "label": "fact",
        "sourceUrl": "https://runningwaterplumbingidaho.com/about-running-water-plumbing-llc/",
        "quote": "New construction and remodel plumbing"
      },
      {
        "statement": "Additional services include radiant heating and annual maintenance plans.",
        "label": "fact",
        "sourceUrl": "https://runningwaterplumbingidaho.com/about-running-water-plumbing-llc/",
        "quote": "Radiant heating and maintenance plans"
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://runningwaterplumbingidaho.com/",
    "claims": [
      {
        "statement": "The company serves Meridian, Boise, Nampa, Kuna, Eagle, Star, Caldwell, and surrounding Treasure Valley communities.",
        "label": "fact",
        "sourceUrl": "https://runningwaterplumbingidaho.com/contact/",
        "quote": "We serve Meridian, Boise, Nampa, Kuna, Eagle, Star, Caldwell, and surrounding areas."
      },
      {
        "statement": "The company intentionally keeps its crew small rather than operating as a large-scale contractor.",
        "label": "fact",
        "sourceUrl": "https://runningwaterplumbingidaho.com/about-running-water-plumbing-llc/",
        "quote": "We keep our crew small to train each plumber the right way, drive clean trucks, and treat every home like it’s our own."
      },
      {
        "statement": "The company offers the Buffalo Bucks annual maintenance plan for $199/year or $19.95/month.",
        "label": "fact",
        "sourceUrl": "https://runningwaterplumbingidaho.com/maintenance-plan/",
        "quote": "For just $199/year or $19.95/month, you get the plumbing support you need without surprise costs or stress."
      },
      {
        "statement": "The company promotes a $50 discount for new customers on qualifying repairs or installations.",
        "label": "fact",
        "sourceUrl": "https://runningwaterplumbingidaho.com/special-offers/",
        "quote": "New customer? Take $50 off any qualifying repair or installation."
      },
      {
        "statement": "Because the company describes its crew as small and lists only a few roles on its team page, it may have fewer than ForgeX's typical 10 to 75 staff range.",
        "label": "inference",
        "sourceUrl": "https://runningwaterplumbingidaho.com/about-running-water-plumbing-llc/",
        "quote": null
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "Running Water Plumbing states that it is a licensed, bonded, and insured plumbing company in Idaho.",
        "label": "fact",
        "sourceUrl": "https://runningwaterplumbingidaho.com/",
        "quote": "Running Water Plumbing is a licensed, bonded and insured plumbing company based in Meridian, ID, serving homes across the Treasure Valley."
      },
      {
        "statement": "Founder [redacted] earned his journeyman certification and subsequently obtained his contractor's license.",
        "label": "fact",
        "sourceUrl": "https://runningwaterplumbingidaho.com/",
        "quote": "After high school, he went straight into plumbing school, earned his journeyman certification, and eventually obtained his contractor’s license to serve his community"
      },
      {
        "statement": "The company states that all of its technicians are licensed and insured.",
        "label": "fact",
        "sourceUrl": "https://runningwaterplumbingidaho.com/meet-the-team/",
        "quote": "Yes. All technicians at Running Water Plumbing LLC are licensed, insured, and properly trained."
      }
    ],
    "limitations": "Specific Idaho plumbing contractor license numbers and state business registration numbers are not published on the pages read."
  },
  "existingSoftware": [
    {
      "product": "Hearth (app.gethearth.com)",
      "purpose": "Customer project financing and monthly payment pre-approval",
      "evidence": {
        "statement": "The financing page states that the company partnered with Hearth to offer customer financing and references host app.gethearth.com.",
        "label": "fact",
        "sourceUrl": "https://runningwaterplumbingidaho.com/financing/",
        "quote": "That’s why we’ve partnered with Hearth to make financing simple and stress-free."
      }
    },
    {
      "product": "clienthub.getjobber.com (Jobber Client Hub)",
      "purpose": "Online booking portal and field-service client hub",
      "evidence": {
        "statement": "Every read page references the host clienthub.getjobber.com alongside 'BOOK ONLINE' calls to action; knowing from outside memory that getjobber.com is the Jobber field-service management platform makes Jobber usage a hypothesis.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "Yahoo Mail ([redacted])",
      "purpose": "Primary public business email inbox",
      "evidence": {
        "statement": "The company publishes [redacted] as its primary contact email address.",
        "label": "fact",
        "sourceUrl": "https://runningwaterplumbingidaho.com/",
        "quote": "[redacted]"
      }
    },
    {
      "product": "WordPress with Elementor Pro, WPForms, Maspik Anti-Spam, and Link Whisper",
      "purpose": "Website content management, page builder, lead capture forms, spam filtering, and internal linking",
      "evidence": {
        "statement": "Script paths on the website reference wp-content/themes/hello-elementor, elementor-pro, google-site-kit events provider for wpforms, contact-forms-anti-spam (maspik), and link-whisper; identifying these products by name from script paths is a hypothesis.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "Google Tag Manager and Google Analytics / Site Kit (googletagmanager.com)",
      "purpose": "Website analytics, tag management, and conversion event tracking",
      "evidence": {
        "statement": "Pages load scripts and frames from www.googletagmanager.com (GT-WR4KJDGL, G-34V76CQ4S6, GTM-K8SWH8WX) and google-site-kit plugin scripts; identifying Google Tag Manager and Google Analytics from these script URLs is a hypothesis.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "One person (co-owner [redacted]) is described as handling scheduling, bookkeeping, and day-to-day administrative details behind the scenes.",
      "label": "fact",
      "sourceUrl": "https://runningwaterplumbingidaho.com/",
      "quote": "[redacted]’s wife, [redacted], helps keep everything running smoothly behind the scenes: handling scheduling, bookkeeping, and the day-to-day details that keep the business flowing!"
    },
    {
      "statement": "The Contact FAQ states that messages typically receive a reply within the hour, especially during regular business hours, rather than an instant 24/7 automated response.",
      "label": "fact",
      "sourceUrl": "https://runningwaterplumbingidaho.com/contact/",
      "quote": "Most messages get a reply within the hour, especially during regular business hours."
    },
    {
      "statement": "The company uses a free consumer email domain ([redacted]) as its published business email address.",
      "label": "fact",
      "sourceUrl": "https://runningwaterplumbingidaho.com/",
      "quote": "[redacted]"
    },
    {
      "statement": "The company sells an annual maintenance plan (Buffalo Bucks) and states that it reminds customers when it is time to schedule their inspection.",
      "label": "fact",
      "sourceUrl": "https://runningwaterplumbingidaho.com/maintenance-plan/",
      "quote": "Anytime that works for you. We’ll remind you if it’s been a while"
    },
    {
      "statement": "Because web form and message replies take up to an hour during business hours and potentially longer after hours, emergency or price-sensitive plumbing leads submitted via web forms may contact competing 24/7 plumbers before receiving a callback.",
      "label": "inference",
      "sourceUrl": "https://runningwaterplumbingidaho.com/contact/",
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "Delayed lead response on web form and message inquiries (up to an hour during business hours, or longer after hours) could cause emergency plumbing prospects to book with another plumber before getting a reply.",
      "label": "hypothesis",
      "basis": "The Contact FAQ states 'Most messages get a reply within the hour, especially during regular business hours,' while the business markets 24/7 emergency plumbing. However, whether leads are actually being lost due to response times cannot be confirmed from public pages."
    },
    {
      "problem": "Manual entry of website form leads and supplier invoices/receipts may create an administrative bottleneck for the co-owner managing scheduling and bookkeeping.",
      "label": "hypothesis",
      "basis": "The homepage states that [redacted] handles scheduling, bookkeeping, and day-to-day details, and the site uses native WordPress forms alongside a Yahoo email address and references to clienthub.getjobber.com. Whether form submissions and supplier invoices require manual re-entry is unconfirmed."
    },
    {
      "problem": "Lack of consolidated weekly KPI visibility across field-service jobs, bookkeeping, and marketing channels.",
      "label": "hypothesis",
      "basis": "The site runs Google tags and promotional offers ($50 off new customer, $150 off online water heater swap), with bookkeeping handled in-house, but it is unknown whether the owners already have satisfactory reporting."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Jobber built-in lead capture, online booking, automated client follow-ups, and reporting (referenced via clienthub.getjobber.com)",
      "addresses": "Online booking, customer reminders for annual maintenance inspections, quote follow-ups, and basic operational reporting.",
      "alreadyOwned": true
    },
    {
      "solution": "Accounting software native bank/receipt capture (e.g., QuickBooks Online receipt forwarding, if used)",
      "addresses": "Basic supplier invoice and receipt intake for bookkeeping.",
      "alreadyOwned": false
    }
  ],
  "forgexSolutions": [
    {
      "name": "Revenue Leak Check",
      "kind": "catalog",
      "description": "One-week audit of calls, WordPress web form leads, messages, and open quotes to quantify how many inquiries slip through or wait too long for a response, with the $500 fee credited toward any fix ordered within 30 days.",
      "problem": "Potential loss of urgent or after-hours plumbing inquiries when messages wait up to an hour (or until business hours) for a human reply.",
      "whyNotExistingSoftware": "While the site links to clienthub.getjobber.com for online booking, every page also embeds multiple native WordPress forms and promotes email/text inquiries; existing tools do not automatically audit cross-channel response gaps across phone, WordPress forms, Yahoo email, and field-service bookings."
    },
    {
      "name": "Lead-to-job pipeline",
      "kind": "catalog",
      "description": "Routes every lead from WordPress contact forms, email, and ad sources into the field-service system within two minutes, sends an instant SMS/email acknowledgment, and tracks callback completion.",
      "problem": "Manual transfer of WordPress form leads into the scheduling system and up-to-one-hour response delays on messages.",
      "whyNotExistingSoftware": "Native WordPress forms on the site post to the website rather than directly into clienthub.getjobber.com; bridging WordPress form submissions, instant SMS replies, and field-service lead creation requires integration beyond out-of-the-box form plugins."
    }
  ],
  "feasibility": {
    "rating": "high",
    "explanation": "Connecting WordPress/Elementor/WPForms submissions via webhook to an instant SMS/email responder and pushing lead records into a field-service platform (such as Jobber) is a standard, well-supported integration."
  },
  "aiDelivery": {
    "rating": "partly",
    "explanation": "Deterministic workflow automation handles form-to-CRM syncing and instant acknowledgment templates reliably, while an AI component can classify inquiry urgency (e.g., 24/7 burst pipe emergency vs. routine quote or Buffalo Bucks plan signup) and draft tailored replies for human dispatch confirmation."
  },
  "humanReview": [
    "Final dispatch commitment and arrival window confirmation for 24/7 emergency plumbing calls must be approved by the on-call plumber or dispatcher.",
    "Any binding price quotes or financing approvals require onsite inspection and human review, consistent with the company's Terms and Conditions.",
    "Any automated bookkeeping or supplier invoice entries should go through a human review queue ([redacted]) before posting to the general ledger."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "In 24/7 emergency plumbing, an automated reply that implies a technician is already en route when no on-call plumber has acknowledged the dispatch could cause severe customer dissatisfaction or property damage."
    },
    {
      "type": "compliance",
      "description": "Automated SMS responses to web form leads require clear opt-in consent language on the website forms to comply with TCPA and carrier messaging regulations."
    },
    {
      "type": "security",
      "description": "Using a consumer Yahoo email account ([redacted]) for customer data and business operations increases credential and deliverability risk if automated integrations rely on consumer inbox credentials."
    }
  ],
  "commercial": {
    "supportable": true,
    "value": "Illustrative value: $2,388 to $4,776 per year in recurring maintenance-plan revenue alone if faster lead capture and follow-up converts 1 to 2 additional Buffalo Bucks annual memberships per month (12 to 24 per year) at the site's published price of $199/year (or $2,872.80 to $5,745.60 per year if billed at the published $19.95/month rate), before counting any standard repair or water heater replacement revenue (for which base prices are not published on the site, only discounts of $50 off a first service and $150 off an online-booked basic water heater swap).",
    "implementationCost": "Revenue Leak Check: $500 fixed price (credited in full toward any fix ordered within 30 days). Lead-to-job pipeline: $1,800 setup plus $149/month ($3,588 first-year total).",
    "assumptions": [
      "Uses only the site's published prices: $199/year or $19.95/month for the Buffalo Bucks Maintenance Program (plus $99/year for additional rental or family homes).",
      "Assumes 1 to 2 additional maintenance plan enrollments per month (12 to 24 per year) are captured through sub-2-minute lead response and automated follow-up.",
      "Base service prices for plumbing repairs and water heater swaps are not published on the website (only $50 and $150 promotional discounts are shown), so one-time repair and installation ticket values are excluded from the calculation."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Founder / Owner (Master/Contractor Plumber)",
      "Co-Owner / Scheduling & Bookkeeping Manager"
    ],
    "people": [
      {
        "name": "[redacted]",
        "role": "Founder",
        "sourceUrl": "https://runningwaterplumbingidaho.com/",
        "quote": "Running Water Plumbing LLC was founded by [redacted], a local Idaho plumber with over 14 years of hands-on experience in the Treasure Valley."
      },
      {
        "name": "[redacted]",
        "role": "Scheduling, Bookkeeping, and Operations (Founder's Wife / Co-leader)",
        "sourceUrl": "https://runningwaterplumbingidaho.com/",
        "quote": "[redacted]’s wife, [redacted], helps keep everything running smoothly behind the scenes: handling scheduling, bookkeeping, and the day-to-day details that keep the business flowing!"
      }
    ],
    "channels": [
      {
        "kind": "email",
        "value": "[redacted]",
        "sourceUrl": "https://runningwaterplumbingidaho.com/"
      }
    ]
  },
  "discovery": {
    "questions": [
      "How many plumbers and office staff are currently on the Running Water Plumbing team, and are you running paid lead campaigns (such as Google Ads or Local Services Ads) alongside organic traffic?",
      "When a homeowner fills out one of the WordPress quote forms on your site (especially evenings or weekends), does that inquiry flow automatically into your scheduling system, or does [redacted] have to enter it manually?",
      "Your Contact FAQ mentions that messages usually get a reply within the hour during business hours—have you noticed any urgent or after-hours leads booking elsewhere before someone can reply?",
      "How much time each week goes into manual bookkeeping, entering supplier invoices from Ferguson or Silvercreek, and tracking Buffalo Bucks maintenance plan renewals?"
    ],
    "outreachSubject": "Question about Running Water Plumbing's website form leads & scheduling",
    "outreachBody": "Hi [redacted],\n\nI was reading through Running Water Plumbing's site and saw how the two of you run the business in Meridian—with [redacted] leading the plumbing crew and [redacted] handling scheduling, bookkeeping, and day-to-day operations.\n\nI noticed your website uses separate WordPress quote forms on each page alongside your online booking link, and your Contact FAQ notes that messages usually get a reply within the hour during business hours. If manual form entry or after-hours response time is ever a bottleneck for [redacted], ForgeX offers a fixed-price Revenue Leak Check ($500, credited in full toward any fix ordered within 30 days) and a Lead-to-Job Pipeline ($1,800 setup + $149/month) that pushes every web form lead directly into your field-service software within two minutes and sends an immediate reply.\n\nIf your current setup with your booking portal already handles everything smoothly, no worries at all—I just wanted to introduce ourselves in case taking repetitive admin off [redacted]'s plate is useful as you grow.\n\nWould you be open to a brief 10-minute chat next week to see if this is relevant to your workflow?\n\nBest regards,\n\n[Founder Name]\n[Title], ForgeX\n[ForgeX Physical Postal Address]\n\nIf you prefer not to receive future emails from us, simply reply with \"unsubscribe\" and we will remove you immediately."
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://runningwaterplumbingidaho.com/",
        "usedFor": "Verified business name, Meridian address, founders [redacted] [redacted], core plumbing services, Buffalo Bucks maintenance plan pricing ($19.95/month or $199/year), email channel, and technical host references."
      },
      {
        "url": "https://runningwaterplumbingidaho.com/about-running-water-plumbing-llc/",
        "usedFor": "Company background, small crew statement, service list (new construction, remodel, radiant heating), and supplier partnerships."
      },
      {
        "url": "https://runningwaterplumbingidaho.com/meet-the-team/",
        "usedFor": "Team composition roles (master plumber, customer care rep, technician) and licensing confirmation."
      },
      {
        "url": "https://runningwaterplumbingidaho.com/contact/",
        "usedFor": "Service area cities, contact methods, and FAQ statement that most messages get a reply within the hour during business hours."
      },
      {
        "url": "https://runningwaterplumbingidaho.com/special-offers/",
        "usedFor": "Published promotional discount amounts ($50 off first service, $150 off basic water heater swap booked online, 5% off for Google review or maintenance plan)."
      },
      {
        "url": "https://runningwaterplumbingidaho.com/maintenance-plan/",
        "usedFor": "Buffalo Bucks maintenance plan pricing ($199/year or $19.95/month), inclusions, and inspection reminder statement."
      },
      {
        "url": "https://runningwaterplumbingidaho.com/plumbing-faq/",
        "usedFor": "Additional service details, emergency procedures, and upfront pricing policy."
      },
      {
        "url": "https://runningwaterplumbingidaho.com/financing/",
        "usedFor": "Verification of Hearth partnership for customer project financing."
      },
      {
        "url": "https://runningwaterplumbingidaho.com/terms-and-conditions/",
        "usedFor": "Legal entity name (Running Water Plumbing LLC) and policy that online/form quotes are estimates subject to onsite inspection."
      },
      {
        "url": "https://runningwaterplumbingidaho.com/privacy-policy/",
        "usedFor": "Data collection practices (forms, estimates, reminders) and contact details."
      }
    ],
    "limitations": [
      "Exact employee headcount is not stated on the website; the About page notes 'We keep our crew small,' so it cannot be confirmed whether the company meets ForgeX's 10 to 75 staff target.",
      "Whether the company pays for leads (e.g., Google Ads or Local Services Ads) cannot be confirmed from the site alone, although Google Tag Manager and conversion tracking scripts are present.",
      "Specific Idaho contractor license numbers are not displayed on the website.",
      "Base prices for standard plumbing repairs and water heater installations are not published on the website (only maintenance plan rates and coupon dollar-off discounts).",
      "Whether the WordPress contact forms are already connected behind the scenes to their field-service system (referenced via clienthub.getjobber.com) cannot be verified from public frontend pages."
    ]
  },
  "qualification": {
    "category": "pursue later",
    "rationale": "Running Water Plumbing LLC is an owner-led residential plumbing contractor in Meridian, Idaho, with clear decision-maker visibility (founder [redacted] and co-leader [redacted], who handles scheduling, bookkeeping, and daily operations) and a valid business contact channel. However, it is categorized as 'pursue later' rather than 'pursue now' for three evidence-based reasons: (1) all potential operational problems—such as lead leakage from 'within the hour' message reply times or manual entry between WordPress forms and their field-service portal—are hypotheses rather than confirmed customer problems; (2) the website already links to an online booking/client portal host (clienthub.getjobber.com), which may already handle core scheduling and reminders; and (3) the About page states 'We keep our crew small,' leaving unconfirmed whether the company has reached ForgeX's 10 to 75 staff segment or actively pays for leads."
  }
}
